def assets(root,cid):
    folder=root/'cases'/cid/'tests/assets'
    return [{'path':str(p.relative_to(root)),'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'bytes':p.stat().st_size} for p in sorted(folder.glob('*')) if p.is_file()]

